import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { checkRateLimit, rateLimitResponse } from "../_shared/rate-limiter.ts";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

interface CreateOrderRequest {
  orderId?: string;
  orderIds?: string[];
  amount?: number;
  sellerId: string;
  customerName: string;
  customerEmail: string;
  customerPhone: string;
}

async function getRazorpayKeys(supabase: any): Promise<{ keyId: string; keySecret: string } | null> {
  const { data: settings } = await supabase
    .from('admin_settings')
    .select('key, value, is_active')
    .in('key', ['razorpay_key_id', 'razorpay_key_secret']);

  if (settings && settings.length === 2) {
    const keyIdSetting = settings.find((s: any) => s.key === 'razorpay_key_id');
    const keySecretSetting = settings.find((s: any) => s.key === 'razorpay_key_secret');

    if (keyIdSetting?.value && keySecretSetting?.value && keyIdSetting.is_active && keySecretSetting.is_active) {
      return { keyId: keyIdSetting.value, keySecret: keySecretSetting.value };
    }
  }

  const envKeyId = Deno.env.get('RAZORPAY_KEY_ID');
  const envKeySecret = Deno.env.get('RAZORPAY_KEY_SECRET');

  if (envKeyId && envKeySecret) {
    return { keyId: envKeyId, keySecret: envKeySecret };
  }

  return null;
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    const razorpayKeys = await getRazorpayKeys(supabase);
    if (!razorpayKeys) {
      console.error('Razorpay keys not configured');
      return new Response(
        JSON.stringify({ error: 'Payment gateway not configured. Please contact admin.' }),
        { status: 503, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const { withAuth } = await import("../_shared/auth.ts");
    const authResult = await withAuth(req, corsHeaders);
    if (authResult instanceof Response) return authResult;
    const user = { id: authResult.userId };

    const { allowed } = await checkRateLimit(`order:${user.id}`, 10, 60);
    if (!allowed) return rateLimitResponse(corsHeaders);

    const body: CreateOrderRequest = await req.json();
    const { sellerId, customerName, customerEmail, customerPhone } = body;
    const clientAmount = body.amount;

    const allOrderIds: string[] = body.orderIds?.length ? body.orderIds : (body.orderId ? [body.orderId] : []);
    if (allOrderIds.length === 0) {
      return new Response(
        JSON.stringify({ error: 'No order IDs provided' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // Validate ALL orders belong to buyer, are not cancelled, and have payment_status: 'pending'
    const { data: orders, error: orderError } = await supabase
      .from('orders')
      .select('id, buyer_id, seller_id, status, payment_status, razorpay_order_id, total_amount, checkout_group_id')
      .in('id', allOrderIds)
      .eq('buyer_id', user.id)
      .neq('status', 'cancelled')
      .eq('payment_status', 'pending');

    if (orderError || !orders || orders.length !== allOrderIds.length) {
      const foundIds = orders?.map((o: any) => o.id) || [];
      const missing = allOrderIds.filter(id => !foundIds.includes(id));
      console.error('Order validation failed. Expected:', allOrderIds.length, 'Found:', orders?.length, 'Missing:', missing);
      return new Response(
        JSON.stringify({ error: 'One or more orders not found, already cancelled, or already paid' }),
        { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const uniqueSellers = new Set(orders.map((o: any) => o.seller_id).filter(Boolean));
    const isMultiSeller = uniqueSellers.size > 1;

    // P5: multi-seller online is platform-collect (one Razorpay payment → N child orders).
    // Route transfers only for single-seller + linked account (below).
    const resolvedSellerId = [...uniqueSellers][0] as string | undefined;
    if (!resolvedSellerId) {
      return new Response(
        JSON.stringify({ error: 'Order is missing seller_id' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }
    if (!isMultiSeller && sellerId && sellerId !== resolvedSellerId) {
      console.warn('Client sellerId mismatch; using order seller_id', { sellerId, resolvedSellerId });
    }

    // Amount from DB only — never trust client-supplied amount
    const dbAmount = orders.reduce((sum: number, o: any) => sum + Number(o.total_amount || 0), 0);
    if (dbAmount <= 0) {
      return new Response(
        JSON.stringify({ error: 'Invalid order total' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }
    if (typeof clientAmount === 'number' && Math.abs(clientAmount - dbAmount) > 0.5) {
      console.warn('[create-razorpay-order] client amount ignored', { client: clientAmount, db: dbAmount });
    }

    console.log('Creating Razorpay order for orders:', allOrderIds, 'amount:', dbAmount, 'sellerId:', resolvedSellerId);

    // Multi-order checkout = platform collect once (merchant of record).
    // Route `transfers` only for a single order with linked seller account below.

    // Idempotency: reuse existing Razorpay order if still valid
    const existingRzpId = orders[0]?.razorpay_order_id;
    const razorpayAuth = btoa(`${razorpayKeys.keyId}:${razorpayKeys.keySecret}`);
    if (existingRzpId) {
      try {
        const fetchRes = await fetch(`https://api.razorpay.com/v1/orders/${existingRzpId}`, {
          headers: { 'Authorization': `Basic ${razorpayAuth}` },
        });
        if (fetchRes.ok) {
          const existingOrder = await fetchRes.json();
          const existingPaise = Number(existingOrder.amount || 0);
          const expectedPaise = Math.round(dbAmount * 100);
          if (
            (existingOrder.status === 'created' || existingOrder.status === 'attempted') &&
            Math.abs(existingPaise - expectedPaise) <= 1
          ) {
            console.log('Reusing existing Razorpay order:', existingRzpId, 'status:', existingOrder.status);
            return new Response(
              JSON.stringify({
                razorpay_order_id: existingOrder.id,
                razorpay_key_id: razorpayKeys.keyId,
                amount: existingOrder.amount,
                currency: existingOrder.currency,
                prefill: { name: customerName, email: customerEmail, contact: customerPhone },
                notes: existingOrder.notes,
                reused: true,
              }),
              { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
            );
          }
          console.log('Existing Razorpay order', existingRzpId, 'not reusable — creating new one');
        }
      } catch (e) {
        console.warn('Failed to fetch existing Razorpay order, creating new one:', e);
      }
    }

    const checkoutGroupId =
      orders.map((o: any) => o.checkout_group_id).find((id: string | null) => !!id) || null;

    const { data: seller } = !isMultiSeller
      ? await supabase
          .from('seller_profiles')
          .select('razorpay_account_id, business_name')
          .eq('id', resolvedSellerId)
          .single()
      : { data: null };

    const amountPaise = Math.round(dbAmount * 100);
    const orderPayload: any = {
      amount: amountPaise,
      currency: 'INR',
      receipt: allOrderIds[0].slice(0, 40),
      notes: {
        order_id: allOrderIds[0],
        order_ids: JSON.stringify(allOrderIds),
        seller_id: isMultiSeller ? 'multi' : resolvedSellerId,
        seller_ids: JSON.stringify([...uniqueSellers]),
        buyer_id: user.id,
        checkout_group_id: checkoutGroupId || '',
        platform_collect: isMultiSeller || allOrderIds.length > 1 ? '1' : '0',
      },
    };

    // Route transfers only for single-order single-seller with linked account.
    // Multi-seller / multi-order = platform collect (partial refunds per child in P4).
    if (!isMultiSeller && allOrderIds.length === 1 && seller?.razorpay_account_id) {
      orderPayload.transfers = [
        {
          account: seller.razorpay_account_id,
          amount: amountPaise,
          currency: 'INR',
          notes: { order_id: allOrderIds[0], type: 'seller_payout' },
          on_hold: 0,
        },
      ];
    }

    console.log('Razorpay order payload:', orderPayload);

    const razorpayResponse = await fetch('https://api.razorpay.com/v1/orders', {
      method: 'POST',
      headers: {
        'Authorization': `Basic ${razorpayAuth}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(orderPayload),
    });

    if (!razorpayResponse.ok) {
      const errorText = await razorpayResponse.text();
      console.error('Razorpay error:', errorText);
      return new Response(
        JSON.stringify({ error: 'Failed to create payment order', details: errorText }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const razorpayOrder = await razorpayResponse.json();
    console.log('Razorpay order created:', razorpayOrder.id, 'for', allOrderIds.length, 'orders');

    for (const oid of allOrderIds) {
      const { error: linkErr } = await supabase
        .from('orders')
        .update({ razorpay_order_id: razorpayOrder.id })
        .eq('id', oid);
      if (linkErr) {
        console.error('Failed to link razorpay_order_id on order', oid, linkErr);
        return new Response(
          JSON.stringify({ error: 'Payment order created but failed to link to Sociva order', details: linkErr.message }),
          { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }
    }

    if (checkoutGroupId) {
      const { error: groupLinkErr } = await supabase
        .from('checkout_groups')
        .update({
          razorpay_order_id: razorpayOrder.id,
          payment_method: 'online',
          updated_at: new Date().toISOString(),
        })
        .eq('id', checkoutGroupId);
      if (groupLinkErr) {
        console.warn('Failed to link razorpay_order_id on checkout_group', checkoutGroupId, groupLinkErr);
      }
    }

    return new Response(
      JSON.stringify({
        razorpay_order_id: razorpayOrder.id,
        razorpay_key_id: razorpayKeys.keyId,
        amount: razorpayOrder.amount,
        currency: razorpayOrder.currency,
        prefill: { name: customerName, email: customerEmail, contact: customerPhone },
        notes: razorpayOrder.notes,
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  } catch (error: unknown) {
    console.error('Error creating order:', error);
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    return new Response(
      JSON.stringify({ error: 'Internal server error', details: errorMessage }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.93.3";

// Module-level shared client — created once per isolate lifetime
let _sharedClient: any = null;
function getSharedClient() {
  if (!_sharedClient) {
    _sharedClient = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
    );
  }
  return _sharedClient;
}

/**
 * Shared rate limiter for edge functions.
 * Uses atomic upsert to prevent race conditions under concurrency.
 * Reuses a module-level Supabase client to avoid cold-start overhead.
 */
export async function checkRateLimit(
  key: string,
  maxRequests: number,
  windowSeconds: number
): Promise<{ allowed: boolean; remaining: number }> {
  try {
    const supabase = getSharedClient();
    const now = new Date();
    const windowStart = new Date(now.getTime() - windowSeconds * 1000);

    const { data: existing } = await supabase
      .from("rate_limits")
      .select("*")
      .eq("key", key)
      .single();

    if (existing) {
      const existingWindowStart = new Date(existing.window_start);

      if (existingWindowStart < windowStart) {
        const { error } = await supabase
          .from("rate_limits")
          .update({ count: 1, window_start: now.toISOString() })
          .eq("key", key)
          .eq("window_start", existing.window_start);

        if (error) {
          return checkRateLimitRetry(supabase, key, maxRequests, windowSeconds);
        }
        return { allowed: true, remaining: maxRequests - 1 };
      }

      if (existing.count >= maxRequests) {
        return { allowed: false, remaining: 0 };
      }

      const { data: updated, error } = await supabase
        .from("rate_limits")
        .update({ count: existing.count + 1 })
        .eq("key", key)
        .eq("count", existing.count)
        .select("count")
        .single();

      if (error || !updated) {
        return checkRateLimitRetry(supabase, key, maxRequests, windowSeconds);
      }

      return { allowed: true, remaining: maxRequests - updated.count };
    }

    await supabase
      .from("rate_limits")
      .upsert(
        { key, count: 1, window_start: now.toISOString() },
        { onConflict: "key" }
      );

    return { allowed: true, remaining: maxRequests - 1 };
  } catch (error) {
    console.error("Rate limiter error (allowing request):", error);
    return { allowed: true, remaining: maxRequests };
  }
}

async function checkRateLimitRetry(
  supabase: any,
  key: string,
  maxRequests: number,
  _windowSeconds: number
): Promise<{ allowed: boolean; remaining: number }> {
  const { data } = await supabase
    .from("rate_limits")
    .select("count")
    .eq("key", key)
    .single();

  if (!data) return { allowed: true, remaining: maxRequests - 1 };

  if (data.count >= maxRequests) {
    return { allowed: false, remaining: 0 };
  }

  const { data: updated, error } = await supabase
    .from("rate_limits")
    .update({ count: data.count + 1 })
    .eq("key", key)
    .eq("count", data.count)
    .select("count")
    .single();

  if (error || !updated) {
    const { data: final } = await supabase.from("rate_limits").select("count").eq("key", key).single();
    if (!final || final.count >= maxRequests) return { allowed: false, remaining: 0 };
    return { allowed: true, remaining: maxRequests - final.count };
  }

  return { allowed: true, remaining: maxRequests - updated.count };
}

export function rateLimitResponse(corsHeaders: Record<string, string>) {
  return new Response(
    JSON.stringify({ error: "Too many requests. Please try again later." }),
    {
      status: 429,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    }
  );
}

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.93.3";

/**
 * Shared auth middleware for edge functions.
 * Extracts and validates Bearer token, returns userId and userClient.
 *
 * Usage:
 *   const authResult = await withAuth(req, corsHeaders);
 *   if (authResult instanceof Response) return authResult;
 *   const { userId, userClient } = authResult;
 */
export async function withAuth(
  req: Request,
  corsHeaders: Record<string, string>
): Promise<{ userId: string; userClient: ReturnType<typeof createClient> } | Response> {
  const authHeader = req.headers.get("Authorization");
  if (!authHeader?.startsWith("Bearer ")) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  const userClient = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_ANON_KEY")!,
    { global: { headers: { Authorization: authHeader } } }
  );

  const { data: { user }, error } = await userClient.auth.getUser();
  if (error || !user) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  return { userId: user.id, userClient };
}
